package com.adent.orders.domain; import com.adent.shared.domain.BaseEntity; import jakarta.persistence.*; import java.time.*; import java.util.UUID; @Entity @Table(name="laboratory_orders") public class LaboratoryOrder extends BaseEntity { @Column(name="tenant_id",nullable=false) private UUID tenantId;@Column(name="patient_id",nullable=false) private UUID patientId;@Column(name="encounter_id") private UUID encounterId;@Column(name="requested_by_staff_id") private UUID requestedByStaffId;@Column(name="tooth_code",length=10) private String toothCode;@Column(name="work_type",nullable=false,length=160) private String workType;@Column(columnDefinition="text") private String instructions;@Column(name="due_date") private LocalDate dueDate;@Column(nullable=false,length=30) private String status="REQUESTED";@Column(name="result_notes",columnDefinition="text") private String resultNotes;@Column(name="delivered_at") private OffsetDateTime deliveredAt; public UUID getTenantId(){return tenantId;}public void setTenantId(UUID v){tenantId=v;}public UUID getPatientId(){return patientId;}public void setPatientId(UUID v){patientId=v;}public UUID getEncounterId(){return encounterId;}public void setEncounterId(UUID v){encounterId=v;}public UUID getRequestedByStaffId(){return requestedByStaffId;}public void setRequestedByStaffId(UUID v){requestedByStaffId=v;}public String getToothCode(){return toothCode;}public void setToothCode(String v){toothCode=v;}public String getWorkType(){return workType;}public void setWorkType(String v){workType=v;}public String getInstructions(){return instructions;}public void setInstructions(String v){instructions=v;}public LocalDate getDueDate(){return dueDate;}public void setDueDate(LocalDate v){dueDate=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getResultNotes(){return resultNotes;}public void setResultNotes(String v){resultNotes=v;}public OffsetDateTime getDeliveredAt(){return deliveredAt;}public void setDeliveredAt(OffsetDateTime v){deliveredAt=v;} }
